export interface SummaryResult {
  summary: string;
  keyPoints: string[];
  mainTopics: string[];
  sentiment: string;
}

export interface FileData {
  name: string;
  content: string;
  type: string;
  size: number;
}

export enum AppStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { SummaryResult, FileData } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const summarizeDocuments = async (files: FileData[], folderUrl: string): Promise<SummaryResult> => {
  // We use gemini-3-pro-preview for complex reasoning and long context
  const model = "gemini-3-pro-preview";

  const combinedContent = files.map(f => `FILE: ${f.name}\nCONTENT:\n${f.content}`).join('\n\n---\n\n');

  const prompt = `
    Analyze the following documents from the folder: ${folderUrl}

    Provided Documents Content:
    ${combinedContent}

    Task: Create a comprehensive "Master Summary" of all information within this folder.
    Identify the main themes, key takeaways, and any patterns or contradictions across the files.
  `;

  const response = await ai.models.generateContent({
    model: model,
    contents: prompt,
    config: {
      temperature: 0.7,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: {
            type: Type.STRING,
            description: "A detailed comprehensive summary of all documents."
          },
          keyPoints: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "Bullet points of the most important information."
          },
          mainTopics: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "High-level topics covered."
          },
          sentiment: {
            type: Type.STRING,
            description: "The overall tone or sentiment of the documents."
          }
        },
        required: ["summary", "keyPoints", "mainTopics", "sentiment"]
      }
    }
  });

  const resultText = response.text || '{}';
  try {
    return JSON.parse(resultText) as SummaryResult;
  } catch (e) {
    console.error("Failed to parse AI response:", resultText);
    throw new Error("Failed to process the AI summary format.");
  }
};

import React, { useState, useCallback, useEffect } from 'react';
