  const combinedContent = files.map(f => `ФАЙЛ: ${f.name}\nСОДЕРЖИМОЕ:\n${f.content}`).join('\n\n---\n\n');

  const prompt = `
    Проанализируй следующие документы из папки: ${folderUrl}

    Содержимое документов:
    ${combinedContent}

    Твоя задача: Создать подробное и структурированное "Общее резюме" по всей информации внутри этой папки.
    Определи основные темы, ключевые выводы и любые закономерности или противоречия между файлами.
    ОТВЕТЬ СТРОГО НА РУССКОМ ЯЗЫКЕ.
  `;

  const response = await ai.models.generateContent({
    model: model,
    contents: prompt,
    config: {
      temperature: 0.7,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: {
            type: Type.STRING,
            description: "Подробное общее резюме всех документов."
          },
          keyPoints: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "Список наиболее важных моментов (буллиты)."
