import { FileData } from '../types';

const DRIVE_API_KEY = process.env.API_KEY;

export const extractFolderId = (url: string): string | null => {
  const match = url.match(/folders\/([a-zA-Z0-9_-]+)/);
  return match ? match[1] : null;
};

export const fetchFolderFiles = async (folderId: string): Promise<FileData[]> => {
  if (!DRIVE_API_KEY) throw new Error("API Key не найден в окружении.");

  // 1. Получаем список файлов в папке
  const listUrl = `https://www.googleapis.com/drive/v3/files?q='${folderId}'+in+parents+and+trashed=false&fields=files(id,name,mimeType)&key=${DRIVE_API_KEY}`;

  const listResponse = await fetch(listUrl);
  if (!listResponse.ok) {
    const error = await listResponse.json();
    throw new Error(`Ошибка Drive API: ${error.error?.message || listResponse.statusText}`);
  }

  const listData = await listResponse.json();
  const files: FileData[] = [];

  // 2. Скачиваем содержимое каждого файла
  for (const file of listData.files) {
    try {
      // Для Google Drive API 'alt=media' позволяет скачать содержимое файла
      const contentUrl = `https://www.googleapis.com/drive/v3/files/${file.id}?alt=media&key=${DRIVE_API_KEY}`;
      const contentResponse = await fetch(contentUrl);

      if (!contentResponse.ok) continue;

      const blob = await contentResponse.blob();
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(blob);
      });

      files.push({
        name: file.name,
        data: base64,
        mimeType: file.mimeType,
        size: blob.size
      });
    } catch (e) {
      console.warn(`Не удалось скачать файл ${file.name}:`, e);
    }
  }

  return files;
};

